    langs.discard("en")
    return sorted(langs)


def _load_flat_split_indices(activation_dir, n, seed=42, ratio=0.7):
    """Get deterministic split indices for pt_flat format."""
    cache_key = (str(activation_dir), n)
    if cache_key in _SPLIT_CACHE:
        return _SPLIT_CACHE[cache_key]

    split_path = Path(activation_dir) / "split_indices.pt"
    if split_path.exists():
        saved = torch.load(split_path, weights_only=True, map_location="cpu")
        train_idx = [int(i) for i in saved["train"] if int(i) < n]
        eval_idx = [int(i) for i in saved["eval"] if int(i) < n]
    else:
        rng = np.random.RandomState(seed)
        perm = rng.permutation(n)
        n_train = int(n * ratio)
        train_idx = sorted(perm[:n_train].tolist())
        eval_idx = sorted(perm[n_train:].tolist())

    _SPLIT_CACHE[cache_key] = (train_idx, eval_idx)
    return train_idx, eval_idx


def load_activations(activation_dir, fmt, layer, lang, split="train", seed=42):
    p = Path(activation_dir)

    if fmt == "npy":
        base = p / f"L{layer}"
        X = np.load(base / f"{lang}_{split}.npy")
        y = np.load(base / f"{lang}_{split}_labels.npy")
    elif fmt == "pt_split":
        data = torch.load(p / f"layer{layer}_{lang}_{split}.pt",
                          weights_only=True, map_location="cpu")
        X, y = data["activations"].numpy(), data["labels"].numpy()
    else:
        data = torch.load(p / f"layer{layer}_{lang}.pt",
                          weights_only=True, map_location="cpu")
        X_all = data["activations"].numpy()
        y_all = data["labels"].numpy()
        train_idx, eval_idx = _load_flat_split_indices(
            activation_dir, len(y_all), seed)
        idx = train_idx if split == "train" else eval_idx
        X, y = X_all[idx], y_all[idx]

    return X.astype(np.float32), y.astype(np.float32)


# ---------------------------------------------------------------------------
# MLP probe
# ---------------------------------------------------------------------------

class MLPProbe(nn.Module):
    def __init__(self, input_dim, hidden_dim=256, dropout=0.1):
        super().__init__()
        self.net = nn.Sequential(
            nn.Linear(input_dim, hidden_dim),
            nn.ReLU(),
            nn.Dropout(dropout),
            nn.Linear(hidden_dim, 1),
        )

    def forward(self, x):
        return self.net(x).squeeze(-1)

    def decision_function(self, X):
        self.eval()
        with torch.no_grad():
            if isinstance(X, np.ndarray):
                X = torch.tensor(X, dtype=torch.float32)
            return self.forward(X).numpy()

    def predict_proba_pos(self, X):
        logits = self.decision_function(X)
        return 1.0 / (1.0 + np.exp(-np.clip(logits, -30, 30)))


def train_mlp(X_train, y_train, hidden_dim=256, dropout=0.1, lr=1e-3,
              epochs=50, patience=5, seed=42):
    torch.manual_seed(seed)
    n = len(y_train)
    n_val = max(int(n * 0.15), min(32, n // 3))
    rng = np.random.RandomState(seed)
    perm = rng.permutation(n)
    val_idx, tr_idx = perm[:n_val], perm[n_val:]

    X_tr = torch.tensor(X_train[tr_idx], dtype=torch.float32)
    y_tr = torch.tensor(y_train[tr_idx], dtype=torch.float32)
    X_val = torch.tensor(X_train[val_idx], dtype=torch.float32)
    y_val = torch.tensor(y_train[val_idx], dtype=torch.float32)

    model = MLPProbe(X_train.shape[1], hidden_dim, dropout)
    optimizer = torch.optim.Adam(model.parameters(), lr=lr)
    criterion = nn.BCEWithLogitsLoss()

    best_loss, best_state, wait = float("inf"), None, 0
    for _ in range(epochs):
        model.train()
        optimizer.zero_grad()
        criterion(model(X_tr), y_tr).backward()
        optimizer.step()

        model.eval()
        with torch.no_grad():
            vloss = criterion(model(X_val), y_val).item()
        if vloss < best_loss:
            best_loss = vloss
            best_state = {k: v.clone() for k, v in model.state_dict().items()}
            wait = 0
        else:
            wait += 1
            if wait >= patience:
                break

    if best_state:
        model.load_state_dict(best_state)
    model.eval()
    return model


